// display.js - the output module's display (U37 U38 U44 U45) on a canvas.
//
// The real display ROM does the work: roms/output-display.hex, the same
// image the hardware burns (generated by tools/genroms.py, encoding in
// docs/hardware.md, "The display"). The output register byte (U44)
// addresses it together with the 7476 mux-counter bits (U45.A8/A9), so
// ROM page p lights the digit whose cathode the 74139 pulls low:
// page 0 = ones (rightmost), 1 = tens, 2 = hundreds, 3 = thousands.
// A10 is the DEC_HEX panel switch (1 = decimal, 0 = hexadecimal;
// leading zeros blanked in both). Data bits: 6=a 5=b 4=c 3=d 2=e 1=f
// 0=g 7=dp.
//
// The hardware multiplexes the four digits at MUX_CLK speed (500+ Hz)
// so they all look lit at once; the canvas draws all four pages every
// frame - the same persistence-of-vision result - while the mux
// counter itself runs (and shows on the panel LEDs, main.js).

export function digitSegments(rom, value, page, decHex) {
  // the ROM address the display hardware forms for one digit
  return rom[(decHex ? 1024 : 0) + (page << 8) + value];
}

// the classic slanted seven-segment digit, in a 34x60 box
const DW = 34, DH = 60, T = 6, GAP = 10, PAD = 9;
const SEG_BOX = {  // bit -> [x1, y1, x2, y2] (see the bit map above)
  6: [5, 4, 29, 4],        // a
  5: [30, 5, 30, 29],      // b
  4: [30, 31, 30, 55],     // c
  3: [5, 56, 29, 56],      // d
  2: [4, 31, 4, 55],       // e
  1: [4, 5, 4, 29],        // f
  0: [5, 30, 29, 30],      // g
};

function hexSeg(ctx, x1, y1, x2, y2, t) {
  // a hexagonal bar stretched along (x1,y1)->(x2,y2), width t: two side
  // pairs plus a pointed cap at each end, like a real segment lens
  const h = t / 2;
  const dx = x2 - x1, dy = y2 - y1;
  const len = Math.hypot(dx, dy) || 1;
  const ux = dx / len * h, uy = dy / len * h;   // along the segment
  const nx = -dy / len * h, ny = dx / len * h;  // across it
  ctx.beginPath();
  ctx.moveTo(x1 - ux, y1 - uy);
  ctx.lineTo(x1 + nx, y1 + ny);
  ctx.lineTo(x2 + nx, y2 + ny);
  ctx.lineTo(x2 + ux, y2 + uy);
  ctx.lineTo(x2 - nx, y2 - ny);
  ctx.lineTo(x1 - nx, y1 - ny);
  ctx.closePath();
  ctx.fill();
}

export function makeDisplay(canvas, rom) {
  const S = 2;  // 2x supersampling: crisp segments on any screen
  const W = PAD * 2 + 4 * DW + 3 * GAP, H = PAD * 2 + DH;
  canvas.width = W * S;
  canvas.height = H * S;
  const ctx = canvas.getContext("2d");
  ctx.scale(S, S);

  function drawDigit(x0, segs, lit) {
    ctx.save();
    ctx.translate(x0, PAD);
    ctx.transform(1, 0, -0.09, 1, 0.09 * DH, 0);  // the slant
    for (const [bit, [x1, y1, x2, y2]] of Object.entries(SEG_BOX)) {
      ctx.fillStyle = (segs >> bit) & 1 ? "#ff3b2f" : "#25100c";
      ctx.shadowBlur = (segs >> bit) & 1 ? 7 : 0;
      ctx.shadowColor = "#ff3b2f";
      hexSeg(ctx, x1, y1, x2, y2, T);
    }
    ctx.restore();
  }

  return {
    /** Paint the four digits the byte lights (persistence-of-vision
     *  view of the 500+ Hz multiplex; the mux counter itself is
     *  emulated in main.js). decHex: 1 = decimal, 0 = hexadecimal. */
    draw(value, decHex) {
      ctx.shadowBlur = 0;
      ctx.fillStyle = "#0d0a07";
      ctx.fillRect(0, 0, W, H);
      for (let p = 0; p < 4; p++) {
        const segs = rom ? digitSegments(rom, value, p, decHex) : 0;
        drawDigit(PAD + (3 - p) * (DW + GAP), segs);
      }
    },
  };
}
